        await http("/console/media/" + item.id, {
          method: "PATCH",
          body: { alt, credit },
        });
      toast("Media saved");
      setFile(null);
      live?.retry();
    } catch (e) {
      toast(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }
  return (
    <Shell
      eyebrow="Asset management"
      title="Media library"
      action={
        <label className={primary}>
          <Icon name="upload" className="h-4 w-4" />
          Upload image
