            placeholder="Search media…"
            className={input + " w-full"}
          />
        </Toolbar>
        <div className="grid lg:grid-cols-[1fr_310px]">
          <div className="grid grid-cols-2 gap-4 p-4 md:grid-cols-3">
            {records.map((x) => (
