                  />
                </div>
                <div className="p-3">
                  <strong className="block truncate text-sm text-ink">
                    {text(x, "alt")}
                  </strong>
                  <span className="text-xs text-slate">
                    {Number(x.size || 0).toLocaleString()} bytes
                  </span>
                </div>
              </button>
            ))}
          </div>
          <aside className="border-t border-line p-5 lg:border-l lg:border-t-0">
