function Rows({ records }: { records?: ConsoleRecord[] }) {
  const live = useConsoleData();
  const source = records || live?.records;
  const stories = source
    ? source.map((x) => [
        text(x, "title"),
        text(x, "author"),
        text(x, "category"),
        text(x, "status"),
